new=r'''
func resizePixels(src [][]Pixel, dstW, dstH int) [][]Pixel {
	srcH := len(src)
	if srcH == 0 || dstW <= 0 || dstH <= 0 {
		return [][]Pixel{}
	}
	srcW := len(src[0])
	if srcW == dstW && srcH == dstH {
		out := make([][]Pixel, srcH)
		for y := range src {
			out[y] = append([]Pixel(nil), src[y]...)
		}
		return out
	}
	// The observed converter uses a separable Lanczos3 resize. Pixels outside
	// image bounds are ignored (not clamped), and the horizontal pass is
	// quantized to 8-bit before the vertical pass.
	tmp := make([][]Pixel, srcH)
	for y := 0; y < srcH; y++ {
		tmp[y] = make([]Pixel, dstW)
		for x := 0; x < dstW; x++ {
			tmp[y][x] = quantPixel(sampleLanczosRow(src[y], srcW, dstW, x))
		}
	}
	out := make([][]Pixel, dstH)
	for y := 0; y < dstH; y++ {
		out[y] = make([]Pixel, dstW)
		weights := lanczosWeights(srcH, dstH, y)
		for x := 0; x < dstW; x++ {
			var p Pixel
			var total float64
			for _, iw := range weights {
				q := tmp[iw.idx][x]
				p.R += q.R * iw.w
				p.G += q.G * iw.w
				p.B += q.B * iw.w
				total += iw.w
			}
			if total != 0 {
				p.R /= total
				p.G /= total
				p.B /= total
			}
			out[y][x] = quantPixel(p)
		}
	}
	return out
}

type idxWeight struct {
	idx int
	w   float64
}

func sampleLanczosRow(row []Pixel, srcN, dstN, outIdx int) Pixel {
	weights := lanczosWeights(srcN, dstN, outIdx)
	var p Pixel
	var total float64
	for _, iw := range weights {
		q := row[iw.idx]
		p.R += q.R * iw.w
		p.G += q.G * iw.w
		p.B += q.B * iw.w
		total += iw.w
	}
	if total != 0 {
		p.R /= total
		p.G /= total
		p.B /= total
	}
	return p
}

func lanczosWeights(srcN, dstN, outIdx int) []idxWeight {
	if srcN == 1 {
		return []idxWeight{{0, 1}}
	}
	scale := float64(srcN) / float64(dstN)
	center := (float64(outIdx)+0.5)*scale - 0.5
	support := 3.0
	radius := support
	if scale > 1 {
